W['who-27']={cap:27,pag:'pp. 362–381',src:SRC(27),abx:'si',res:'Neumonía comunitaria grave: mayor riesgo de mortalidad a corto plazo, requiere ingreso hospitalario o UCI. Los criterios y esquemas son los del capítulo 12 (misma infografía). Considerar añadir un macrólido para cubrir atípicos (Chlamydia, Mycoplasma pneumoniae). Duración habitual: 5 días.',
 pat:['Streptococcus pneumoniae','Haemophilus influenzae','Mycoplasma pneumoniae y otros atípicos','Staphylococcus aureus','Bacilos gramnegativos'],
 alertas:['CURB-65 ≥ 3: ingreso (valorar UCI); 2: valorar ingreso y añadir claritromicina; los laboratorios ayudan a valorar gravedad y a distinguir infección bacteriana de viral.','Si es grave y el paciente no está estable al día 5, considerar tratamiento más largo y buscar complicaciones (p. ej. empiema).','Niños con neumonía grave (o que no toleran la vía oral): ingreso con antibiótico IV.'],
 grupos:[G('Adultos',[E('Neumonía grave',[D('W','Cefotaxima 2 g c/8 h IV/IM'),D('W','Ceftriaxona 2 g c/24 h IV (1 g c/24 h IM)'),D('W','Si CURB-65 ≥ 2: añadir claritromicina 500 mg c/12 h VO (o IV)')],[D('A','Amoxicilina + ácido clavulánico 1 g + 200 mg c/8 h IV (dosis mayor posible: 1 g + 200 mg c/6 h)'),D('W','Si CURB-65 ≥ 2: añadir claritromicina 500 mg c/12 h VO (o IV)')],'5 días (más si grave y no estable al día 5)','La claritromicina tiene excelente biodisponibilidad oral; reservar la vía IV a quien no pueda usar el tubo digestivo.')]),
  G('Niños',[E('Neumonía grave',[D('A','Amoxicilina 50 mg/kg/dosis IV/IM (≤ 1 semana de vida c/12 h; > 1 semana c/8 h)'),D('A','Ampicilina 50 mg/kg/dosis IV/IM (≤ 1 semana c/12 h; > 1 semana c/8 h)'),D('A','Bencilpenicilina 30 mg/kg/dosis (50 000 UI/kg/dosis) c/8 h IV'),D('A','Combinada con gentamicina IV/IM: neonatos 5 mg/kg c/24 h; niños 7.5 mg/kg c/24 h')],[D('W','Sin respuesta a las 48–72 h: cefotaxima 50 mg/kg/dosis c/8 h IV/IM o ceftriaxona 80 mg/kg/dosis c/24 h IV/IM')],'3 días si prevalencia baja de VIH y sin tiraje · 5 días si prevalencia alta de VIH o con tiraje','Si es VIH positivo y < 1 año: añadir sulfametoxazol + trimetoprima 40 mg/kg SMX + 8 mg/kg TMP c/8 h IV/VO durante 3 semanas.')])]};
W['who-28']={cap:28,pag:'pp. 382–396',src:SRC(28),abx:'si',res:'Considerar suspender si se descarta la NIH o hay un diagnóstico alternativo; si el paciente no está grave, tratar según resultados microbiológicos. El tratamiento empírico se guía por la gravedad, la prevalencia local de resistencia y los factores de riesgo individuales.',
 pat:['Enterobacterales','Staphylococcus aureus (incluido SARM)','Pseudomonas aeruginosa y Acinetobacter (sobre todo en ventilación mecánica)'],
 alertas:['Prevención: vacunación, higiene de manos, movilidad, higiene oral y dental, nutrición, cabecera elevada, evitar o acortar la intubación; en UCI: minimizar sedación, evaluar extubación, descontaminación digestiva selectiva (con vigilancia de resistencia).','Neumonía asociada a ventilador (NAV): valorar necesidad de doble cobertura antipseudomonas (riesgo de infección por aislados resistentes a un antibiótico en monoterapia).','Simplificar el tratamiento empírico a un espectro más estrecho según cultivos o mejoría; pasar a oral según la evolución.','Piperacilina + tazobactam ofrece cobertura antipseudomonas, a diferencia de las otras opciones (mayor riesgo de P. aeruginosa en estancia hospitalaria prolongada, exposición previa a antibióticos, colonización respiratoria conocida o enfermedad pulmonar de base).'],
 grupos:[G('Adultos',[E('NIH no asociada a ventilador (bajo riesgo de multirresistentes)',[D('A','Amoxicilina + ácido clavulánico 1 g + 200 mg c/8 h IV o 875 mg + 125 mg c/8 h VO (si hospitalización corta antes del inicio y sin antibióticos previos)'),D('W','Cefotaxima 2 g c/8 h IV/IM'),D('W','Ceftriaxona 2 g c/24 h IV (1 g c/24 h IM)'),D('W','Piperacilina + tazobactam 4 g + 500 mg c/6 h IV (cobertura antipseudomonas)')],[],'7 días (reevaluar el diagnóstico; más tiempo si no hay estabilidad clínica al día 7)','')]),
  G('Niños',[E('NIH no asociada a ventilador',[D('A','Amoxicilina + ácido clavulánico: IV 1.ª semana 50 mg/kg/dosis de amoxicilina c/12 h; después c/8 h; VO 80–90 mg/kg/día. '+bandsAmClav),D('W','Cefotaxima 50 mg/kg/dosis c/8 h IV/IM'),D('W','Ceftriaxona 80 mg/kg/dosis c/24 h IV/IM'),D('W','Piperacilina + tazobactam 100 mg/kg/dosis (componente piperacilina) c/8 h IV')],[],'7 días (reevaluar el diagnóstico; más tiempo si no hay estabilidad clínica al día 7)','')])]};
W['who-29']={cap:29,pag:'pp. 397–413',src:SRC(29),abx:'si',res:'La colecistectomía (colecistitis) y el drenaje biliar (colangitis) son los pilares para eliminar el foco; el tratamiento empírico se guía por gravedad, resistencia local (sobre todo Enterobacterales productores de BLEE) y factores de riesgo individuales.',
 pat:['Enterobacterales (E. coli, Klebsiella)','Enterococcus','Anaerobios'],
 alertas:['Simplificar el esquema según cultivos o mejoría; pasar a vía oral según evolución.','Si persisten los signos y síntomas, sospechar complicación o foco extrabiliar: imagen abdominal.','Ciprofloxacino y metronidazol tienen excelente biodisponibilidad oral: reservar la IV para quien no tolera la vía digestiva.','Meropenem: solo en casos complicados con alto riesgo de Enterobacterales productores de BLEE.'],
 grupos:[G('Adultos',[
  E('Casos leves',[D('A','Amoxicilina + ácido clavulánico 1 g + 200 mg c/8 h IV o 875 mg + 125 mg c/8 h VO'),D('W','Cefotaxima 2 g c/8 h IV + metronidazol 500 mg c/8 h IV/VO'),D('W','Ceftriaxona 2 g c/24 h IV + metronidazol 500 mg c/8 h IV/VO')],[D('W','Ciprofloxacino 500 mg c/12 h VO + metronidazol 500 mg c/8 h IV/VO')],'Colecistitis no complicada: se puede suspender tras la colecistectomía · Colecistitis complicada: 5 días suelen bastar con buena recuperación y control del foco · Colangitis: hasta drenaje biliar y total de 5 días tras el control exitoso del foco',''),
  E('Casos graves',[D('W','Cefotaxima 2 g c/8 h IV + metronidazol 500 mg c/8 h IV/VO'),D('W','Ceftriaxona 2 g c/24 h IV + metronidazol 500 mg c/8 h IV/VO'),D('W','Piperacilina + tazobactam 4 g + 500 mg c/6 h IV')],[D('W','Meropenem 1 g c/8 h IV (solo en casos complicados con alto riesgo de BLEE)')],'Igual que en casos leves','')]),
 G('Niños',[
  E('Casos leves',[D('A','Amoxicilina + ácido clavulánico: IV 1.ª semana 50 mg/kg/dosis (amoxicilina) c/12 h, después c/8 h; VO 80–90 mg/kg/día. '+bandsAmClav),D('A','Ampicilina IV (1.ª semana 50 mg/kg/dosis c/12 h; después c/8 h) + gentamicina IV (neonatos 5 mg/kg c/24 h; niños 7.5 mg/kg c/24 h) + '+metroNeo+'. Bandas de metronidazol VO: '+bandsMetro),D('W','Cefotaxima 50 mg/kg/dosis c/8 h IV o ceftriaxona 80 mg/kg/dosis c/24 h IV + metronidazol IV/VO (misma dosis)')],[D('W','Ciprofloxacino 15 mg/kg/dosis c/12 h IV/VO + metronidazol IV/VO. Bandas de ciprofloxacino: '+bandsCipro)],'Igual que en adultos',''),
  E('Casos graves',[D('A','Ampicilina IV (1.ª semana 50 mg/kg/dosis c/12 h; después c/8 h) + gentamicina IV (neonatos 5 mg/kg c/24 h; niños 7.5 mg/kg c/24 h) + '+metroNeo),D('W','Piperacilina + tazobactam 100 mg/kg/dosis (componente piperacilina) c/8 h IV')],[D('W','Meropenem 20 mg/kg/dosis c/8 h IV (solo en casos complicados con alto riesgo de BLEE)')],'Igual que en adultos','')])]};
