W['who-39']={cap:39,pag:'pp. 563–578',src:SRC(39),abx:'si',res:'Los pacientes con neutropenia grave (< 500 células/µL o < 0.5 × 10⁹/L) que desarrollan fiebre deben recibir antibiótico de inmediato, aunque no se identifique el foco.',
 pat:['Bacilos gramnegativos (incl. BLEE y productores de carbapenemasas)','Staphylococcus aureus (SARM)'],
 alertas:['Bajo riesgo: manejo ambulatorio con seguimiento si tolera la vía oral. Alto riesgo (o sin seguimiento cercano posible): hospitalizar e iniciar IV, pasar a oral al mejorar clínicamente y quedar afebril.','Si la fiebre persiste 48–72 h sin mejoría clínica, buscar foco, complicaciones locales, organismo resistente o infección no bacteriana.','Considerar retirar el catéter venoso central infectado.','Reevaluar la necesidad de continuar tratamiento combinado según cultivos y respuesta.','Considerar meropenem solo donde hay alta prevalencia de BLEE o colonización/infección previa por resistentes.'],
 grupos:[G('Adultos',[E('Bajo riesgo',[D('A','Amoxicilina + ácido clavulánico 500 mg + 125 mg c/8 h VO'),D('W','Considerar añadir ciprofloxacino 500 mg c/12 h VO')],[],'7 días',''),
   E('Alto riesgo',[D('W','Piperacilina + tazobactam 4 g + 500 mg c/6 h IV')],[D('W','Meropenem 1 g c/8 h IV')],'Hasta resolución de signos clínicos de infección Y ≥ 48 h sin fiebre','Considerar añadir a cualquiera: amikacina 15 mg/kg c/24 h IV (si bacterias gramnegativas resistentes) y/o vancomicina 15–20 mg/kg c/12 h IV (si SARM).')]),
  G('Niños',[E('Bajo riesgo',[D('A','Amoxicilina + ácido clavulánico 80–90 mg/kg/día VO. '+bandsAmClav),D('W','Considerar añadir ciprofloxacino 15 mg/kg/dosis c/12 h VO. '+bandsCipro)],[],'7 días',''),
   E('Alto riesgo',[D('W','Piperacilina + tazobactam 100 mg/kg/dosis c/8 h IV')],[D('W','Meropenem 20 mg/kg/dosis c/8 h IV')],'Hasta resolución de signos clínicos de infección Y ≥ 48 h sin fiebre','Considerar añadir a cualquiera: amikacina 15 mg/kg c/24 h IV y/o vancomicina IV (neonatos 15 mg/kg c/12 h; niños 15 mg/kg c/8 h).')])]};
